(()=>{const all=[...document.querySelectorAll('[data-stop]')],pins=[...document.querySelectorAll('.geo-pin')],choices=[...document.querySelectorAll('.journey-choice')],map=document.querySelector('.geo-canvas'),popup=document.querySelector('#journey-popup'),close=popup.querySelector('.popup-close');const stories=[['01 / BOULDER, CO','Where it all started','Studied chemical engineering at the University of Colorado. I met my best friends here and had the time of my life. Sko Buffs!'],['02 / BEND, OR','Learning from the best','I worked on developing new processes for manufacturing monoclonal antibodies. I had the best mentors here and learned so much about what good leadership looks like.'],['03 / CORVALLIS, OR · ONLINE','A degree alongside full-time work','I completed my online Computer Science degree while working full time at Lonza. This was a tough time with a lot of long nights, but I\'m glad I did this!'],['04 / LONDON, UK','Across the Atlantic','My work at Lonza culminated in a pilot scale transfer of the new process we developed in Bend. I\'m so proud of closing the process engineering chapter of my career with this achievement. I also proposed to my wife here! 💍'],['05 / SEATTLE, WA · REMOTE','Trading processes for code','My first developer role at a really fast-paced startup. I couldn’t have asked for a better landing spot for a career pivot. A perfect fit for my background, a great place to learn the craft and grow in the age of AI!'],['06 / PORTLAND, OR · REMOTE','Where I’m at now','There has never been a better time to be a builder. At Seeq, I get to build solutions for the hardest problems in industrial analytics. It’s a fun place to watch frontier models evolve and to utilize them every day!']];let current=-1,anchor=null,timer;const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));function position(){if(current<0||popup.hidden)return;const mr=map.getBoundingClientRect(),pr=pins[current].getBoundingClientRect(),w=popup.offsetWidth,h=popup.offsetHeight,cx=pr.left-mr.left+pr.width/2,cy=pr.top-mr.top+pr.height/2;let x=clamp(cx+26,8,mr.width-w-8),y=clamp(cy-h/2,8,mr.height-h-8);if(cx+26+w>mr.width-8)x=clamp(cx-w-26,8,mr.width-w-8);popup.style.left=x+'px';popup.style.top=y+'px';popup.style.setProperty('--tail-y',clamp(cy-y,24,h-24)+'px');popup.classList.toggle('tail-right',x<cx);popup.classList.toggle('no-tail',cx>=x&&cx<=x+w)}function show(i,source){clearTimeout(timer);current=i;anchor=source;popup.querySelector('.popup-place').textContent=stories[i][0];popup.querySelector('h3').textContent=stories[i][1];popup.querySelector('p').textContent=stories[i][2];const companies={0:['University of Colorado Boulder','assets/logos/cu-boulder.png'],1:['Lonza','assets/logos/lonza.svg'],2:['Oregon State University','assets/logos/oregon-state.svg'],3:['Lonza','assets/logos/lonza.svg'],4:['Invert','assets/logos/invert.svg'],5:['Seeq','assets/logos/seeq.png']};const company=popup.querySelector('.popup-company'),logo=company.querySelector('img');company.hidden=!companies[i];if(companies[i]){logo.src=companies[i][1];logo.alt=companies[i][0]}else{logo.removeAttribute('src');logo.alt=''};all.forEach(b=>{const on=Number(b.dataset.stop)===i;b.classList.toggle('active',on);b.setAttribute('aria-expanded',String(on))});popup.hidden=false;position()}function hide(){clearTimeout(timer);popup.hidden=true;current=-1;all.forEach(b=>{b.classList.remove('active');b.setAttribute('aria-expanded','false')})}function leave(){clearTimeout(timer);timer=setTimeout(()=>{if(!popup.matches(':hover')&&!popup.contains(document.activeElement)&&!all.includes(document.activeElement))hide()},240)}all.forEach(b=>{const i=Number(b.dataset.stop);b.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')show(i,b)});b.addEventListener('pointerleave',e=>{if(e.pointerType!=='touch')leave()});b.addEventListener('focus',()=>show(i,b));b.addEventListener('blur',leave);b.addEventListener('click',()=>show(i,b));b.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%6;else if(e.key==='ArrowLeft')n=(i+5)%6;else if(e.key==='Home')n=0;else if(e.key==='End')n=5;else return;e.preventDefault();(b.classList.contains('geo-pin')?pins:choices)[n].focus()})});popup.addEventListener('pointerenter',()=>clearTimeout(timer));popup.addEventListener('pointerleave',leave);close.addEventListener('click',()=>{hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!popup.hidden){hide();if(anchor){anchor.focus();hide()}}});document.addEventListener('pointerdown',e=>{if(!popup.contains(e.target)&&!e.target.closest('[data-stop]'))hide()});addEventListener('resize',position);map.querySelector('img').addEventListener('load',position)})();
